/* @autogenerated */
package net.civeira.phylax.features.oauth.tokensecurity.application;

import java.util.List;
import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

class SubjectResolverUnitTest {

  private final SubjectResolver resolver = new SubjectResolver(Optional.of("salt"));

  @Test
  @DisplayName("The sector is the sector_identifier_uri host, else the single redirect host")
  void sector() {
    Assertions.assertEquals(Optional.of("rp.example"),
        SubjectResolver.sector("https://rp.example/sector.json", List.of("https://x.example/cb")));
    Assertions.assertEquals(Optional.of("app.example"), SubjectResolver.sector(null,
        List.of("https://app.example/cb", "https://app.example/other")));
    Assertions.assertTrue(SubjectResolver
        .sector(null, List.of("https://a.example/cb", "https://b.example/cb")).isEmpty());
  }

  @Test
  @DisplayName("Clients of the same sector share the subject; other sectors and users differ")
  void pairwise() {
    String a = resolver.subject(true, null, List.of("https://app.example/cb"), "alice");
    Assertions.assertEquals(a,
        resolver.subject(true, "https://app.example/s.json", List.of(), "alice"));
    Assertions.assertNotEquals(a,
        resolver.subject(true, null, List.of("https://other.example/cb"), "alice"));
    Assertions.assertNotEquals(a,
        resolver.subject(true, null, List.of("https://app.example/cb"), "bob"));
    Assertions.assertEquals("alice", resolver.subject(false, null, List.of(), "alice"));
  }

  @Test
  @DisplayName("Without salt or sector a pairwise subject is refused")
  void fail_closed() {
    Assertions.assertThrows(IllegalStateException.class, () -> new SubjectResolver(Optional.empty())
        .subject(true, null, List.of("https://app.example/cb"), "alice"));
    Assertions.assertThrows(IllegalStateException.class, () -> resolver.subject(true, null,
        List.of("https://a.example/cb", "https://b.example/cb"), "alice"));
  }
}
